using System.Net;
using System.Net.Http.Json;
using System.Security.Cryptography;
using System.Text;
using System.Text.Json;
using BuildingFlow.Application;
using BuildingFlow.Domain;
using BuildingFlow.Infrastructure;
using Microsoft.EntityFrameworkCore;
using Microsoft.Extensions.DependencyInjection;
using Xunit;
namespace BuildingFlow.IntegrationTests;
public sealed class MobileRequestDetailsTests(SiteApiTests.SiteApiFactory factory):IClassFixture<SiteApiTests.SiteApiFactory>{
 private async Task<(HttpClient Client,Guid Property,string User,Guid Member)> Setup(){var user=Guid.NewGuid().ToString();var p=new Property("Request fixture","City","District","Address");var m=new PropertyMembership(p.Id,user);await factory.WithDb(async db=>{db.AddRange(p,m);await db.SaveChangesAsync();});return(TestToken.Client(factory,user,"MANAGER"),p.Id,user,m.Id);}
 private static MobileSyncCommand Cmd(Guid p)=>new(Guid.NewGuid(),Guid.NewGuid(),p,null,"MANAGER","CREATE",0,"Fixture request","FAULT","HIGH");
 private static Task<HttpResponseMessage> Push(HttpClient c,MobileSyncCommand cmd)=>c.PostAsJsonAsync("/api/v1/mobile/sync/commands",cmd);
 private static Task<HttpResponseMessage> Photo(HttpClient c,Guid id)=>c.GetAsync($"/api/v1/mobile/sync/requests/{id}/photo");
 private static string Image()=>Convert.ToBase64String(File.ReadAllBytes(Path.Combine(AppContext.BaseDirectory,"Fixtures","avatar.jpg")));
 [PostgresFact]public async Task DetailsReplayAndVersionRulesAreStable(){var s=await Setup();using var c=s.Client;var cmd=Cmd(s.Property);var created=(await(await Push(c,cmd)).Content.ReadFromJsonAsync<MobileSyncResult>())!;Assert.Equal("FAULT",created.Record.Category);Assert.Equal("HIGH",created.Record.Priority);Assert.True((await(await Push(c,cmd)).Content.ReadFromJsonAsync<MobileSyncResult>())!.Replayed);Assert.Equal(HttpStatusCode.Conflict,(await Push(c,cmd with{Priority="LOW"})).StatusCode);Assert.Equal(HttpStatusCode.BadRequest,(await Push(c,cmd with{OperationId=Guid.NewGuid(),Category="INVALID"})).StatusCode);var update=cmd with{OperationId=Guid.NewGuid(),Action="UPDATE",ExpectedVersion=created.Record.Version,Category="CLEANING",Priority="NORMAL"};var changed=(await(await Push(c,update)).Content.ReadFromJsonAsync<MobileSyncResult>())!;Assert.Equal("CLEANING",changed.Record.Category);Assert.Equal(HttpStatusCode.Conflict,(await Push(c,update with{OperationId=Guid.NewGuid()})).StatusCode);}
 [PostgresFact]public async Task LegacyReceiptFingerprintStillReplaysAfterNewFields(){var s=await Setup();using var c=s.Client;var cmd=new MobileSyncCommand(Guid.NewGuid(),Guid.NewGuid(),s.Property,null,"MANAGER","CREATE",0,"Legacy fixture");var serialized=JsonSerializer.Serialize(new{cmd.OperationId,cmd.RecordId,cmd.PropertyId,cmd.UnitId,cmd.Role,cmd.Action,cmd.ExpectedVersion,cmd.Description});var fingerprint=Convert.ToHexString(SHA256.HashData(Encoding.UTF8.GetBytes(serialized)));await factory.WithDb(async db=>{var r=new MobileRequest(cmd.RecordId,s.Property,null,"MANAGER",s.User,cmd.Description!);db.Add(r);await db.SaveChangesAsync();var legacy=JsonSerializer.Serialize(new{r.Id,r.PropertyId,r.UnitId,Role="MANAGER",r.Description,r.Version,Deleted=false,r.ModifiedAt});db.Add(new MobileOperationReceipt(s.User,cmd.OperationId,fingerprint,legacy));await db.SaveChangesAsync();});var response=await Push(c,cmd);Assert.Equal(HttpStatusCode.OK,response.StatusCode);Assert.True((await response.Content.ReadFromJsonAsync<MobileSyncResult>())!.Replayed);}
 [StorageFact]public async Task PhotoCreateConcurrentReplayAndPrivateDownloadAreIdempotent(){var s=await Setup();using var c=s.Client;await ConsentTestHelper.GrantAsync(factory,c,"REQUEST_PHOTO");var cmd=Cmd(s.Property) with{PhotoAction="REPLACE",PhotoBase64=Image()};var responses=await Task.WhenAll(Push(c,cmd),Push(c,cmd));Assert.All(responses,r=>Assert.Equal(HttpStatusCode.OK,r.StatusCode));var records=await Task.WhenAll(responses.Select(r=>r.Content.ReadFromJsonAsync<MobileSyncResult>()));Assert.Equal(records[0]!.Record.PhotoId,records[1]!.Record.PhotoId);Assert.NotNull(records[0]!.Record.PhotoSha256);var photo=await Photo(c,cmd.RecordId);Assert.Equal(HttpStatusCode.OK,photo.StatusCode);var bytes=await photo.Content.ReadAsByteArrayAsync();Assert.Equal(records[0]!.Record.PhotoSha256,Convert.ToHexString(SHA256.HashData(bytes)));using var foreign=TestToken.Client(factory,Guid.NewGuid().ToString(),"MANAGER");using var accountant=TestToken.Client(factory,s.User,"ACCOUNTANT");using var anon=TestToken.Client(factory,null,"");Assert.Equal(HttpStatusCode.Forbidden,(await Photo(foreign,cmd.RecordId)).StatusCode);Assert.Equal(HttpStatusCode.Unauthorized,(await Photo(anon,cmd.RecordId)).StatusCode);Assert.Equal(HttpStatusCode.Forbidden,(await Photo(accountant,cmd.RecordId)).StatusCode);var snapshot=(await c.GetFromJsonAsync<MobileRequestSnapshot>($"/api/v1/mobile/sync/requests?propertyId={s.Property}&role=MANAGER"))!;Assert.Equal(records[0]!.Record.PhotoId,Assert.Single(snapshot.Records).PhotoId);}
 [StorageFact]public async Task ReplaceRemoveDeleteAndStorageCleanupPreserveTombstones(){var s=await Setup();using var c=s.Client;await ConsentTestHelper.GrantAsync(factory,c,"REQUEST_PHOTO");var cmd=Cmd(s.Property) with{PhotoAction="REPLACE",PhotoBase64=Image()};var first=(await(await Push(c,cmd)).Content.ReadFromJsonAsync<MobileSyncResult>())!;var edit=cmd with{OperationId=Guid.NewGuid(),Action="UPDATE",ExpectedVersion=first.Record.Version};var second=(await(await Push(c,edit)).Content.ReadFromJsonAsync<MobileSyncResult>())!;Assert.NotEqual(first.Record.PhotoId,second.Record.PhotoId);var remove=edit with{OperationId=Guid.NewGuid(),ExpectedVersion=second.Record.Version,PhotoAction="REMOVE",PhotoBase64=null};var removed=(await(await Push(c,remove)).Content.ReadFromJsonAsync<MobileSyncResult>())!;Assert.Null(removed.Record.PhotoId);Assert.Equal(HttpStatusCode.NotFound,(await Photo(c,cmd.RecordId)).StatusCode);var attach=edit with{OperationId=Guid.NewGuid(),ExpectedVersion=removed.Record.Version};var third=(await(await Push(c,attach)).Content.ReadFromJsonAsync<MobileSyncResult>())!;var del=attach with{OperationId=Guid.NewGuid(),Action="DELETE",ExpectedVersion=third.Record.Version,Description=null,Category=null,Priority=null,PhotoAction="KEEP",PhotoBase64=null};var deleted=(await(await Push(c,del)).Content.ReadFromJsonAsync<MobileSyncResult>())!;Assert.True(deleted.Record.Deleted);Assert.Null(deleted.Record.PhotoId);Assert.Equal(HttpStatusCode.NotFound,(await Photo(c,cmd.RecordId)).StatusCode);using var scope=factory.Services.CreateScope();await scope.ServiceProvider.GetRequiredService<IMobileSyncStore>().MaintainAsync(default);await factory.WithDb(async db=>{Assert.All(await db.Set<MobileRequestPhoto>().Where(x=>x.OwnerUserId==s.User).ToArrayAsync(),x=>Assert.Equal("PURGED",x.State));});}
 [StorageFact]public async Task RevokedMembershipCannotReplayOrDownloadPhoto(){var s=await Setup();using var c=s.Client;await ConsentTestHelper.GrantAsync(factory,c,"REQUEST_PHOTO");var cmd=Cmd(s.Property) with{PhotoAction="REPLACE",PhotoBase64=Image()};Assert.Equal(HttpStatusCode.OK,(await Push(c,cmd)).StatusCode);await factory.WithDb(async db=>{var member=await db.PropertyMemberships.FindAsync(s.Member);member!.SetEnabled(false);await db.SaveChangesAsync();});Assert.Equal(HttpStatusCode.Forbidden,(await Push(c,cmd)).StatusCode);Assert.Equal(HttpStatusCode.Forbidden,(await Photo(c,cmd.RecordId)).StatusCode);}
 [PostgresFact]public async Task MalformedOversizedAndUnexpectedPhotosAreRejected(){var s=await Setup();using var c=s.Client;var cmd=Cmd(s.Property);Assert.Equal(HttpStatusCode.BadRequest,(await Push(c,cmd with{PhotoAction="REPLACE",PhotoBase64="not an image"})).StatusCode);Assert.Equal(HttpStatusCode.BadRequest,(await Push(c,cmd with{PhotoBase64=Image()})).StatusCode);Assert.Equal(HttpStatusCode.BadRequest,(await Push(c,cmd with{PhotoAction="REPLACE",PhotoBase64=Convert.ToBase64String(new byte[262145])})).StatusCode);using var oversized=new StringContent("{\"value\":\""+new string('x',400001)+"\"}",Encoding.UTF8,"application/json");Assert.Equal(HttpStatusCode.RequestEntityTooLarge,(await c.PostAsync("/api/v1/mobile/sync/commands",oversized)).StatusCode);}
}
